    "jurisdiction": "Delaware, USA",
    "industry_code": "332999",
    "period_end": "2024-12-31",
    "is_public": false
  },
  "components": [
    {
      "section_ref": "MR-01",
      "standard_ref": "AU-C 580.10a",
      "text": "Management has fulfilled its responsibilities for the preparation and fair presentation of the financial statements in accordance with US GAAP.",
      "evidence_refs": ["WP-2024-0457-001", "WP-2024-0457-012"]
    },
    {
      "section_ref": "MR-02",
      "standard_ref": "AU-C 580.10b",
      "text": "Management has provided the auditor with all relevant information and access as agreed in the engagement letter dated 2024-01-15.",
